"use strict";
let shopBooting=false,shopBootTimer=0,shopBootAudio=null;
function authenticKeys(){return `<div class="real-n73-controls"><div class="real-soft"><button aria-label="N73左选择键（关机）">—</button><button class="real-green" aria-label="N73通话键（关机）">⌕</button></div><div class="real-stick"><i></i></div><div class="real-soft"><button aria-label="N73右选择键（关机）">—</button><button class="real-red" aria-label="N73结束键（关机）">⌕</button></div></div><div class="real-keydeck"><div class="real-rail"><button aria-label="N73菜单键（关机）">▦</button><button aria-label="N73编辑键（关机）">✎</button></div><div class="real-digits">${[['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ'],['*','+'],['0',''],['#','↑']].map(([n,t])=>`<button aria-label="N73数字键${n}（关机）"><b>${n}</b><small>${t}</small></button>`).join('')}</div><div class="real-rail"><button aria-label="N73多媒体键（关机）">▧</button><button aria-label="N73清除键（关机）">C</button></div></div>`;}
const authenticHeldBase=shopHandsetMarkup;
shopHandsetMarkup=function(){if(shopHandset!=='black')return authenticHeldBase();return `<section class="shop-held-phone authentic-held"><button data-hands-put ${shopBooting?'disabled':''}>放回维修垫</button><div class="real-n73 ${shopBooting?'booting':''}"><button class="real-power" data-hands-power aria-label="N73顶部电源键" ${shopBooting?'disabled':''}>⏻</button><div class="real-earpiece"><i></i><i></i><i></i><i></i><i></i></div><div class="real-camera"></div><div class="real-name">NOKIA <span>Nseries</span></div><div class="real-screen">${shopBooting?'<div class="boot-screen"><b>NOKIA</b><div class="boot-hands"><svg viewBox="0 0 240 110" role="img" aria-label="双手慢慢靠近的重制启动动画"><g class="boot-left"><path d="M0 42L58 42L77 34L108 41L128 59L113 82L85 81L61 65L0 66Z" fill="#d9b796" stroke="#90785e"/><path d="M0 37L48 38L48 73L0 76Z" fill="#244573"/><path d="M78 46L104 50L121 65M78 57L109 67M83 68L108 77" fill="none" stroke="#a3866a"/></g><g class="boot-right"><path d="M240 40L181 43L160 34L142 37L114 53L105 64L114 70L135 58L157 77L180 69L240 68Z" fill="#e9c6a3" stroke="#9c8165"/><path d="M240 35L195 38L194 75L240 79Z" fill="#284d7e"/><path d="M137 58L154 70M145 52L166 66" stroke="#af8f70" fill="none"/></g></svg></div><audio id="shop-boot-sound" src="audio/oldlane-startup.wav" preload="auto"></audio><small>Connecting People</small></div>':'<span class="real-dark">屏幕未亮</span>'}</div><span class="real-side-volume">━<br>━</span>${authenticKeys()}<span class="real-mic">•</span></div>${shopBooting?'<p role="status">屏幕亮起，正在启动……</p>':'<label class="boot-mute"><input type="checkbox" data-boot-mute '+(nightShop.bootMute?'checked':'')+'> 静音开机</label><p>顶部是电源键。按下后播放开机画面。</p>'}<small class="boot-credit">N73 外观与启动体验为网页重制，音效为原创复古合成音。</small></section>`;};
const authenticPowerBase=shopPower;
function shopBootFinish(){if(!shopBooting)return false;shopBooting=false;clearTimeout(shopBootTimer);if(shopBootAudio){shopBootAudio.pause?.();shopBootAudio=null;}return authenticPowerBase();}
shopPower=function(){if(shopHandset!=='black')return authenticPowerBase();if(shopBooting)return false;shopBooting=true;openShop();if(!nightShop.bootMute){shopBootAudio=document.querySelector('#shop-boot-sound');if(shopBootAudio?.play){shopBootAudio.volume=.55;shopBootAudio.play().catch(()=>{});}}shopBootTimer=setTimeout(shopBootFinish,3600);return true;};
try{nightShop.bootMute=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.bootMute===true;}catch{}
document.addEventListener('change',e=>{if(e.target.matches('[data-boot-mute]')){nightShop.bootMute=e.target.checked;tideSave();}});
const authenticObjectsBase=shopObjectMarkup;
shopObjectMarkup=function(){let h=authenticObjectsBase();if(shopObject==='drawer'&&!shopDetail&&!shopHandset){h=h.replace('<span class="moved-cards">挪开的保修卡</span>','<button class="aside-cards" data-shifted="cards" aria-label="挪到旁边的保修卡，点一下放回">保修卡<br><small>已挪到左侧</small></button>');if(nightShop.rummaged.includes('battery'))h=h.replace('<div class="closeup-table drawer-table','<div class="closeup-table drawer-table').replace('aria-label="打开的抽屉近景">','aria-label="打开的抽屉近景"><button class="aside-battery" data-shifted="battery" aria-label="挪到旁边的电池，点一下放回">BL-5C<br><small>3.7V</small></button>');}if(shopObject==='counter'&&!shopDetail&&nightShop.rummaged.includes('slip'))h=h.replace('prop prop-ledger','prop prop-ledger ledger-aside').replace('data-shop-rummage="slip"','data-shifted="slip"').replace('翻开价目册','价目册 / 已挪开');return h;};
function shopPutLayer(id){if(!['cards','battery','slip'].includes(id)||(id==='slip'?shopObject!=='counter':shopObject!=='drawer'))return false;nightShop.rummaged=nightShop.rummaged.filter(k=>k!==id&&(id!=='cards'||k!=='battery'));tideSave();return true;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-shifted]');if(!b)return;shopPutLayer(b.dataset.shifted);openShop();});

document.querySelector('#modal')?.addEventListener('close',()=>{if(!shopBooting)return;shopBooting=false;clearTimeout(shopBootTimer);shopBootAudio?.pause?.();shopBootAudio=null;});
